using System;using System.IO;using System.Text;using System.Linq;using System.Security.Cryptography;using System.Windows;using System.Windows.Controls;using System.Collections.Generic;
namespace KianaPet {
 public sealed class SharedPreferenceSnapshot {public int Schema=1;public string Product="KianaSharedPreferences",Device,Revision,ParentRevision,Package;public DateTime CreatedAt;}
 public sealed class SharedPreferenceRead {public string Hash;public SharedPreferenceSnapshot Snapshot;public PreferenceImportInfo Info;}
 public static class SharedPreferences {
  public static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");}
  public static SharedPreferenceRead Read(string path){var fi=new FileInfo(path);if(!fi.Exists)return null;if(fi.Length>262144)throw new Exception("共享快照超过 256 KB。");byte[] data=File.ReadAllBytes(path);if(data.Length>262144)throw new Exception("共享快照超过 256 KB。");var snapshot=Store.Json.Deserialize<SharedPreferenceSnapshot>(Encoding.UTF8.GetString(data).TrimStart('\uFEFF'));if(snapshot==null||snapshot.Schema!=1||snapshot.Product!="KianaSharedPreferences"||string.IsNullOrWhiteSpace(snapshot.Revision)||snapshot.Package==null)throw new Exception("不是支持的桌宠共享快照。");var info=PreferenceReview.Parse(snapshot.Package);info.PresentKeys=info.PresentKeys.Where(k=>!PreferenceReview.Local(k)).ToArray();return new SharedPreferenceRead{Hash=Hash(data),Snapshot=snapshot,Info=info};}
  public static SharedPreferenceRead Publish(string path,Config c,string expectedHash){path=Path.GetFullPath(path);if(!Directory.Exists(Path.GetDirectoryName(path)))throw new Exception("请先建立共享文件所在目录。");using(var gate=new FileStream(path+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){
   var prior=Read(path);if((prior==null?null:prior.Hash)!=expectedHash)throw new Exception("共享快照已变化，请重新检查差异后再发布，未覆盖其他设备的修改。");
   var snapshot=new SharedPreferenceSnapshot{Device=Environment.MachineName,Revision=Guid.NewGuid().ToString("N"),ParentRevision=prior==null?null:prior.Snapshot.Revision,CreatedAt=DateTime.UtcNow,Package=PreferenceTransfer.Export(c,false)};
   byte[] data=new UTF8Encoding(false).GetBytes(Store.Json.Serialize(snapshot));if(data.Length>262144)throw new Exception("共享快照过大。");string tmp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var output=new FileStream(tmp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(data,0,data.Length);output.Flush(true);}if(File.Exists(path))File.Replace(tmp,path,null);else File.Move(tmp,path);}finally{if(File.Exists(tmp))File.Delete(tmp);}return Read(path);
  }}
 }
 public sealed class SharedPreferenceReviewWindow:Window {
  readonly PetWindow pet;readonly string path;readonly SharedPreferenceRead incoming;readonly Dictionary<string,CheckBox> choices=new Dictionary<string,CheckBox>();readonly TextBlock summary;readonly Button apply;
  public SharedPreferenceReviewWindow(PetWindow owner,string file,SharedPreferenceRead read){pet=owner;path=file;incoming=read;Title="共享偏好 · 选择要应用的修改";Width=760;Height=650;MinWidth=540;MinHeight=420;WindowStartupLocation=WindowStartupLocation.CenterOwner;PetVisuals.Apply(this,true);Background=PetPalette.Brush(PetPalette.Background);Foreground=PetPalette.Brush(PetPalette.Ink);var dock=new DockPanel{Margin=new Thickness(22)};var top=new StackPanel();top.Children.Add(CompanionControls.Text("来自 "+read.Snapshot.Device+" · "+read.Snapshot.CreatedAt.ToLocalTime().ToString("yyyy-MM-dd HH:mm"),18));top.Children.Add(CompanionControls.Text("只应用勾选的通用偏好。本机路径、连接方式、位置、自动规则及外部通知开关保留。",12));summary=CompanionControls.Text("");top.Children.Add(summary);var bulk=new WrapPanel();foreach(bool select in new[]{true,false}){bool value=select;bulk.Children.Add(CompanionControls.Button(select?"全选":"全不选",delegate{foreach(var box in choices.Values)box.IsChecked=value;Refresh();}));}top.Children.Add(bulk);DockPanel.SetDock(top,Dock.Top);dock.Children.Add(top);var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right};actions.Children.Add(CompanionControls.Button("取消",delegate{DialogResult=false;}));apply=CompanionControls.Button("备份并应用",Apply);actions.Children.Add(apply);DockPanel.SetDock(actions,Dock.Bottom);dock.Children.Add(actions);var rows=new StackPanel();var merged=PreferenceReview.Merge(pet.PersistentPreferences(),incoming.Info,false,false);foreach(var row in PreferenceReview.Differences(pet.PersistentPreferences(),merged)){var box=new CheckBox{Content=row.Label,IsChecked=true,Foreground=Foreground,Margin=new Thickness(0,4,0,8)};choices[row.Key]=box;box.Checked+=delegate{Refresh();};box.Unchecked+=delegate{Refresh();};var content=new StackPanel();content.Children.Add(box);content.Children.Add(CompanionControls.Text("本机："+row.Before+"\n共享："+row.After,12));rows.Children.Add(new Border{Child=content,Padding=new Thickness(12),Margin=new Thickness(0,0,8,10),BorderThickness=new Thickness(1),BorderBrush=PetPalette.Brush(PetPalette.Line),CornerRadius=new CornerRadius(12)});}dock.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Content=dock;Refresh();}
  void Refresh(){int count=choices.Values.Count(c=>c.IsChecked==true);summary.Text="已选择 "+count+" 项修改";if(apply!=null)apply.IsEnabled=count>0;}
  async void Apply(){try{IsEnabled=false;var latest=await System.Threading.Tasks.Task.Run(()=>SharedPreferences.Read(path));if(!IsLoaded)return;if(latest==null||latest.Hash!=incoming.Hash)throw new Exception("共享快照在预览期间发生变化，请取消并重新检查。");var current=pet.PersistentPreferences();var proposed=PreferenceReview.Merge(current,incoming.Info,false,false);foreach(var field in typeof(Config).GetFields()){CheckBox box;if(!choices.TryGetValue(field.Name,out box)||box.IsChecked!=true)field.SetValue(proposed,field.GetValue(current));}pet.PauseAutoScenes();string warning=pet.ReplacePreferences(proposed,false);if(warning.Length>0)MessageBox.Show(this,warning,"偏好已应用");DialogResult=true;}catch(Exception e){if(IsLoaded)MessageBox.Show(this,e.Message,"尚未应用");}finally{if(IsLoaded)IsEnabled=true;}}
 }
}
